(() => {
'use strict';

// Little Kitchen: a standalone local-first recipe diary. No account or API key required.
const DB_NAME = 'little-kitchen-recipes-v1';
const DB_VERSION = 2;
const demo = [
  {id:'demo-soup',title:'Velvety Pumpkin Soup',category:'food',description:'',minutes:35,servings:4,difficulty:'Easy',photo:'./assets/pumpkin-soup.svg',favorite:true,ingredients:['2 tbsp olive oil','1 small onion, diced','2 garlic cloves, minced','3 cups pumpkin purée','2 cups vegetable broth','½ cup coconut milk or cream','½ tsp cinnamon','Salt, pepper and pumpkin seeds to taste'],notes:'A swirl of cream and toasted pumpkin seeds make this extra lovely. If it is too thick, stir in a splash of warm broth.',steps:[{id:'s1',text:'Warm the olive oil in a pot. Add the onion and cook until soft, about 5 minutes.',note:'A gentle heat brings out its natural sweetness.'},{id:'s2',text:'Stir in the garlic, pumpkin and cinnamon. Cook for 2 minutes until fragrant.',note:''},{id:'s3',text:'Pour in the vegetable broth and simmer gently for 15 minutes.',note:''},{id:'s4',text:'Blend until silky, stir in coconut milk, season and ladle into bowls.',note:'Finish with pumpkin seeds and a pretty cream swirl.'}]},
  {id:'demo-rolls',title:'Maple Cinnamon Rolls',category:'dessert',description:'',minutes:110,servings:9,difficulty:'Cozy project',photo:'./assets/cinnamon-rolls.svg',favorite:true,ingredients:['2¾ cups all-purpose flour','2¼ tsp instant yeast','¾ cup warm milk','3 tbsp melted butter','¼ cup sugar','1 egg','½ cup brown sugar','2 tsp cinnamon','3 tbsp softened butter for filling','½ cup powdered sugar','2 tbsp maple syrup'],notes:'Allow the dough to double in size before shaping; glaze while warm.',steps:[{id:'s1',text:'Mix flour, yeast, warm milk, melted butter, sugar and egg. Knead into a soft dough.',note:'Add flour a spoon at a time only if needed.'},{id:'s2',text:'Cover and let the dough rise until doubled, around 45–60 minutes.',note:''},{id:'s3',text:'Roll into a rectangle. Spread with softened butter, brown sugar and cinnamon.',note:''},{id:'s4',text:'Roll up, cut into 9 spirals and nestle into a greased baking dish.',note:''},{id:'s5',text:'Rest 15 minutes, then bake at 350°F / 175°C for 23–28 minutes.',note:'Mix powdered sugar with maple syrup and drizzle on warm rolls.'}]},
  {id:'demo-chai',title:'Honey Chai Latte',category:'drink',description:'',minutes:12,servings:2,difficulty:'Easy',photo:'./assets/chai-latte.svg',favorite:false,ingredients:['2 black tea bags','1 cup water','1 cup milk of choice','1 cinnamon stick','2 cardamom pods, cracked','2 cloves','1–2 tbsp honey','Pinch of ground cinnamon'],notes:'Oat milk froths beautifully. Add extra honey or ginger to make it your own.',steps:[{id:'s1',text:'Simmer water with cinnamon, cardamom and cloves for 5 minutes.',note:''},{id:'s2',text:'Turn off the heat, add the tea bags and steep for 3 minutes.',note:''},{id:'s3',text:'Strain, stir in honey and pour into two mugs.',note:''},{id:'s4',text:'Warm and froth milk, then pour it gently over the tea.',note:'Dust the top with cinnamon.'}]},
  {id:'demo-apple',title:'Sunday Apple Crumble',category:'dessert',description:'',minutes:55,servings:6,difficulty:'Easy',photo:'./assets/apple-crumble.svg',favorite:false,ingredients:['5 apples, peeled and sliced','2 tbsp brown sugar','1 tsp cinnamon','1 tbsp lemon juice','¾ cup flour','¾ cup rolled oats','½ cup cold butter, cubed','⅓ cup brown sugar for topping'],notes:'Tart apples balance the sweetness. Add vanilla ice cream when you serve it.',steps:[{id:'s1',text:'Preheat oven to 375°F / 190°C. Toss apple slices with brown sugar, cinnamon and lemon.',note:''},{id:'s2',text:'Put the apple filling in a baking dish.',note:''},{id:'s3',text:'Rub flour, oats, butter and remaining sugar together until crumbly.',note:''},{id:'s4',text:'Scatter the crumble over the apples and bake 35–40 minutes.',note:'Let stand 10 minutes before serving.'}]},
  {id:'demo-pasta',title:'Garden Herb Pasta',category:'food',description:'',minutes:25,servings:3,difficulty:'Easy',photo:'./assets/herb-pasta.svg',favorite:false,ingredients:['10 oz pasta','2 tbsp olive oil','2 cloves garlic, sliced','1 cup cherry tomatoes, halved','1 lemon, zest and juice','½ cup fresh basil','¼ cup grated parmesan','Salt and black pepper'],notes:'Save a cup of pasta water. A splash makes the lemony sauce glossy and silky.',steps:[{id:'s1',text:'Boil pasta in salted water until al dente. Reserve ½ cup pasta water.',note:''},{id:'s2',text:'Sauté garlic in olive oil for 1 minute. Add tomatoes and soften for 4 minutes.',note:''},{id:'s3',text:'Toss pasta with tomatoes, lemon zest, juice and a splash of pasta water.',note:''},{id:'s4',text:'Fold through basil and parmesan. Season and serve immediately.',note:''}]},
  {id:'demo-cider',title:'Spiced Apple Cider',category:'drink',description:'',minutes:30,servings:4,difficulty:'Easy',photo:'./assets/spiced-cider.svg',favorite:true,ingredients:['4 cups fresh apple cider','1 orange, sliced','2 cinnamon sticks','3 whole cloves','1 star anise (optional)','Maple syrup to taste'],notes:'Keep the heat low so the spices can infuse without boiling.',steps:[{id:'s1',text:'Pour apple cider into a saucepan. Add orange slices and whole spices.',note:''},{id:'s2',text:'Heat until steaming, then reduce to a very gentle simmer.',note:''},{id:'s3',text:'Simmer for 20 minutes. Taste and sweeten with maple syrup if needed.',note:''},{id:'s4',text:'Strain into mugs and garnish with a cinnamon stick.',note:''}]},
  {id:'demo-rice',title:'Creamy Cinnamon Rice Pudding',category:'dessert',description:'',minutes:45,servings:4,difficulty:'Easy',photo:'./assets/rice-pudding.svg',favorite:false,ingredients:['¾ cup short-grain rice','3 cups whole milk or oat milk','½ cup water','¼ cup sugar','1 tsp vanilla','½ tsp cinnamon','Pinch of salt','Raisins or chopped nuts, optional'],notes:'Stir often over low heat to prevent scorching. The pudding thickens as it cools.',steps:[{id:'s1',text:'Rinse and soak the rice in cool water for 15 minutes, then drain.',note:'Take a photo of the soaked rice here if you like.'},{id:'s2',text:'Pour the milk and ½ cup water into a heavy pot. Add the drained rice and a pinch of salt.',note:'A photo here can show the milk level before cooking.'},{id:'s3',text:'Bring to a gentle simmer and stir often for 25–30 minutes until creamy.',note:'Keep the heat low so the milk does not scorch.'},{id:'s4',text:'Stir in sugar, vanilla and cinnamon. Serve warm or chilled.',note:'Top with a little extra cinnamon.'}]},
  {id:'demo-brownies',title:'Fudgy Cocoa Brownies',category:'dessert',description:'',minutes:40,servings:9,difficulty:'Easy',photo:'./assets/brownie.svg',favorite:false,ingredients:['½ cup butter, melted','1 cup sugar','2 eggs','1 tsp vanilla','½ cup cocoa powder','½ cup all-purpose flour','¼ tsp salt','½ cup chocolate chips'],notes:'Pull the brownies out while the center still has a few moist crumbs. Cool before slicing.',steps:[{id:'s1',text:'Preheat oven to 350°F / 175°C. Line an 8-inch pan with parchment.',note:''},{id:'s2',text:'Whisk melted butter, sugar, eggs and vanilla until glossy.',note:''},{id:'s3',text:'Fold in cocoa, flour, salt and chocolate chips without overmixing.',note:''},{id:'s4',text:'Spread into pan and bake 22–27 minutes. Cool before cutting.',note:''}]}
].map((r,i)=>({...r,createdAt:new Date(Date.now()-(i+1)*86400000).toISOString(),updatedAt:new Date(Date.now()-(i+1)*86400000).toISOString(),steps:r.steps.map(s=>({...s,photo:''}))}));

const CATS={food:{label:'Food',plural:'Food recipes',art:'./assets/herb-pasta.svg',desc:'Heartwarming meals and savory little favorites'},drink:{label:'Drinks',plural:'Drink recipes',art:'./assets/chai-latte.svg',desc:'Little sips, warm mugs and refreshing pours'},dessert:{label:'Desserts',plural:'Dessert recipes',art:'./assets/cinnamon-rolls.svg',desc:'Something sweet for the happiest endings'}};
const NAV=[['grocery','Groceries','basket'],['recipes','Recipes','book'],['food','Food','utensils'],['drink','Drinks','coffee'],['dessert','Desserts','cake']];
const ICONS={
 basket:'<path d="M4 10h16l-2 11H6L4 10zM8 10l4-7 4 7M3 10h18M9 14v4m6-4v4"/>',
 cart:'<circle cx="9" cy="20" r="1"/><circle cx="19" cy="20" r="1"/><path d="M2 3h2l3 13h13l2-9H5"/>',
 bag:'<path d="M4 8h16l-1 13H5L4 8zM9 9V6a3 3 0 0 1 6 0v3"/>',
 store:'<path d="M3 10l2-7h14l2 7-2 3v8H5v-8l-2-3zM3 10h18M10 21v-7h5v7"/>',
 minus:'<path d="M5 12h14"/>',
 sort:'<path d="M4 7h16M7 12h10M10 17h4"/>',
 home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',
 book:'<path d="M12 7q-4-3-9-2v15q5-1 9 2 4-3 9-2V5q-5-1-9 2z"/><path d="M12 7v15"/>',
 utensils:'<path d="M4 3v7m4-7v7M6 3v18M3 10h6M18 3c-3 2-4 6-4 10h4v8"/>',
 coffee:'<path d="M4 8h13v7a6.5 6.5 0 0 1-13 0z"/><path d="M17 9h2a3 3 0 0 1 0 6h-2M3 21h17M8 2v3M13 2v3"/>',
 cake:'<path d="M4 11h16v10H4zM4 15c2 2 4-2 6 0s4-2 6 0 4-2 4 0M12 3v5M9 8h6M12 2v1"/>',
 settings:'<path d="M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4M18.4 5.6 17 7M7 17l-1.4 1.4"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1.5"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',back:'<path d="M15 18 9 12l6-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M20 21v-2a4 4 0 0 0-3-3.9M16 3a4 4 0 0 1 0 8"/>',heart:'<path d="M20.8 4.6c-2-2-5.3-2-7.3 0L12 6l-1.5-1.4c-2-2-5.3-2-7.3 0s-2 5.2 0 7.2L12 21l8.8-9.2c2-2 2-5.2 0-7.2z"/>',camera:'<path d="M4 7h3l2-3h6l2 3h3a1 1 0 0 1 1 1v11H3V8a1 1 0 0 1 1-1z"/><circle cx="12" cy="13" r="3.3"/>',edit:'<path d="M4 20h5L20 9l-5-5L4 15zM13 6l5 5"/>',trash:'<path d="M4 7h16M9 7V4h6v3m3 0-1 14H7L6 7M10 11v6m4-6v6"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',close:'<path d="M5 5l14 14M19 5 5 19"/>',chevron:'<path d="m9 18 6-6-6-6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',upload:'<path d="M12 21V9m-5 5 5-5 5 5M4 7V3h16v4"/>',check:'<path d="m4 12 5 5L20 6"/>',sparkles:'<path d="m12 2 2 8 8 2-8 2-2 8-2-8-8-2 8-2zM19 3v4M17 5h4"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="2"/><path d="m21 15-5-5L5 21"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h1M3 12h1M3 18h1"/>',leaf:'<path d="M20 4c-10-1-17 5-17 12a4 4 0 0 0 4 4c7 0 13-7 13-16zM5 19q5-8 12-11"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',moon:'<path d="M20 15a8 8 0 0 1-11-11 8 8 0 1 0 11 11z"/>',star:'<path d="m12 2 3 7 7 1-5.5 5 1.4 7L12 18l-5.9 4 1.4-7L2 10l7-1z"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>'};
const icon=(name,size=18)=>`<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${ICONS[name]||ICONS.sparkles}</svg>`;
const esc=(x)=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>globalThis.crypto?.randomUUID?.()||'r-'+Date.now()+'-'+Math.random().toString(36).slice(2);
let db,recipes=[],groceries=[],prefs={glow:true,theme:'cinnamon',budget:0},tab='grocery',previousTab='grocery',selected=null,query='',filter='all',favoritesOnly=false,editor=null,overlay='',photoTarget=null,toastTimeout,checked={},grocerySearch='',groceryFilter='all',groceryCategory='all',groceryStore='all',groceryGroup='category',groceryDraft=null,groceryPickerRecipe='',groceryPickerSelected=new Set(),pendingGroceryId=null;
const $=s=>document.querySelector(s);
const screen=$('#screen'),root=$('#overlay-root'),header=$('#app-header'),nav=$('#bottom-nav');

function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const d=req.result;if(!d.objectStoreNames.contains('recipes'))d.createObjectStore('recipes',{keyPath:'id'});if(!d.objectStoreNames.contains('meta'))d.createObjectStore('meta',{keyPath:'key'});if(!d.objectStoreNames.contains('groceries'))d.createObjectStore('groceries',{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function readAll(store){return new Promise((resolve,reject)=>{const t=db.transaction(store,'readonly');const req=t.objectStore(store).getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function put(store,obj){return new Promise((resolve,reject)=>{const t=db.transaction(store,'readwrite');t.objectStore(store).put(obj);t.oncomplete=resolve;t.onerror=()=>reject(t.error);});}
function del(store,key){return new Promise((resolve,reject)=>{const t=db.transaction(store,'readwrite');t.objectStore(store).delete(key);t.oncomplete=resolve;t.onerror=()=>reject(t.error);});}
function clear(store){return new Promise((resolve,reject)=>{const t=db.transaction(store,'readwrite');t.objectStore(store).clear();t.oncomplete=resolve;t.onerror=()=>reject(t.error);});}
async function initialize(){try{db=await openDB();const records=await readAll('meta');const stored=Object.fromEntries(records.map(v=>[v.key,v.value]));prefs={glow:stored.glow!==false,theme:stored.theme||'cinnamon',budget:Number(stored.budget)||0};recipes=await readAll('recipes');groceries=await readAll('groceries');if(!stored.initialized){for(const r of demo)await put('recipes',r);recipes=await readAll('recipes');await put('meta',{key:'initialized',value:true});}render();if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});}catch(err){console.error(err);screen.innerHTML=`<div class="empty"><h3>Couldn't open your recipe diary</h3><p>Your browser may be blocking storage. Try opening this site in a normal browser tab rather than a private window.</p></div>`;}}
const sortRec=(arr)=>[...arr].sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||''));
const byId=r=>recipes.find(x=>x.id===r);
const niceDate=()=>new Intl.DateTimeFormat('en-US',{weekday:'long',month:'long',day:'numeric'}).format(new Date());
function notify(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>t.classList.remove('show'),2600);}
function scrollTop(){screen.scrollTop=0;}
function applyTheme(){document.body.classList.toggle('ambient-off',!prefs.glow);document.body.classList.toggle('cream-mode',prefs.theme==='maple');}
function render({keepScroll=false}={}){const scroll=screen.scrollTop;applyTheme();renderHeader();renderNav();const r=selected&&byId(selected);if(selected&&!r)selected=null;screen.innerHTML=selected&&r?recipeDetail(r):tab==='grocery'?groceryView():tab==='settings'?settingsView():listView();if(keepScroll)screen.scrollTop=scroll;else scrollTop();}
function renderHeader(){
 if(selected){header.innerHTML=`<button class="icon-circle" data-action="back" aria-label="Back to recipes">${icon('back')}</button><div class="brand heading-brand"><span class="brand-mini">RECIPE BOOK</span><span class="brand-name">${esc(byId(selected)?.title||'Recipe')}</span></div><button class="icon-circle" data-action="edit" aria-label="Edit recipe">${icon('edit')}</button>`;return;}
 header.innerHTML=`<div class="header-identity"><button class="brand-emblem brand-trigger" data-action="settings" aria-label="Open Settings" title="Settings"><img src="./assets/icon.svg" alt=""></button><div class="brand-label"><span class="brand-mini">THE LITTLE</span><div class="brand-name">Kitchen <span class="brand-leaf">✦</span></div></div></div><div class="header-right"><button class="icon-circle" data-action="${tab==='grocery'?'grocery-new':tab==='settings'?'settings-back':'new'}" title="${tab==='grocery'?'Add grocery item':tab==='settings'?'Back to groceries':'Add recipe'}" aria-label="${tab==='grocery'?'Add grocery item':tab==='settings'?'Back to groceries':'Add recipe'}">${icon(tab==='settings'?'close':'plus')}</button></div>`;
}
function renderNav(){nav.innerHTML=NAV.map(([key,label,ic])=>`<button type="button" class="nav-btn ${tab===key?'active':''}" data-tab="${key}" ${tab===key?'aria-current="page"':''} aria-label="${label}">${icon(ic,24)}<span>${label}</span></button>`).join('');}

function card(r){const cat=CATS[r.category]||CATS.food;return `<article class="recipe-card"><img class="thumb" src="${esc(r.photo||cat.art)}" alt="${esc(r.title)}" loading="lazy"><button class="card-hit" data-action="open" data-id="${esc(r.id)}" aria-label="Open ${esc(r.title)}"></button><button class="heart-btn ${r.favorite?'saved':''}" data-action="favorite" data-id="${esc(r.id)}" aria-label="${r.favorite?'Remove from':'Add to'} favorites">${icon('heart')}</button><div class="card-body"><span class="category-label">${cat.label}</span><h3>${esc(r.title)}</h3><div class="card-meta"><span>${icon('clock',12)} ${esc(r.minutes)} min</span><span>${icon('users',12)} ${esc(r.servings)} servings</span></div></div></article>`;}
function listView(){const isAll=tab==='recipes',cat=CATS[tab],base=recipes.filter(r=>isAll||r.category===tab);const shown=sortRec(base.filter(r=>(!favoritesOnly||r.favorite)&&(filter==='all'||r.difficulty===filter)&&[r.title,r.description,r.ingredients.join(' ')].some(s=>s.toLowerCase().includes(query.toLowerCase()))));return `<div class="eyebrow">${isAll?'ALL RECIPES':esc(cat.label).toUpperCase()}</div><h1 class="page-title">${isAll?'Recipe <em>book</em>':esc(cat.label)}</h1>
<div class="search-bar">${icon('search')}<input id="recipe-search" autocomplete="off" aria-label="Search recipes" placeholder="Search a recipe or ingredient…" value="${esc(query)}"><span style="font-size:10px;color:#e3b287">${base.length}</span></div>
<div class="chip-list"><button class="chip ${!favoritesOnly&&filter==='all'?'selected':''}" data-action="clear-filter">All recipes</button><button class="chip ${favoritesOnly?'selected':''}" data-action="fav-filter">♡ Favorites</button><button class="chip ${filter==='Easy'?'selected':''}" data-action="difficulty" data-value="Easy">Easy</button><button class="chip ${filter==='Cozy project'?'selected':''}" data-action="difficulty" data-value="Cozy project">Cozy projects</button></div>
${shown.length?`<div class="recipe-grid">${shown.map(card).join('')}</div>`:`<div class="empty"><h3>No recipes found</h3><p>${query||favoritesOnly||filter!=='all'?'Change your search or filters.':'Add your first recipe.'}</p><button class="btn" data-action="new">${icon('plus')} New recipe</button></div>`}<button class="floating-add" data-action="new" title="New recipe" aria-label="Add new recipe">${icon('plus',25)}</button>`;}
function recipeDetail(r){const cat=CATS[r.category]||CATS.food;const ingredientChecks=checked[r.id]||[];return `<div class="detail-cover"><img src="${esc(r.photo||cat.art)}" alt="${esc(r.title)}"><span class="pill cover-tag">${cat.label}</span></div><div class="detail-top"><h1 class="page-title">${esc(r.title)}</h1>${r.description?`<p class="detail-description">${esc(r.description)}</p>`:''}<div class="action-row"><button class="btn secondary small" data-action="favorite" data-id="${esc(r.id)}">${icon('heart')} ${r.favorite?'Saved favorite':'Save favorite'}</button><button class="btn secondary small" data-action="edit">${icon('edit')} Edit recipe</button></div></div>
<div class="detail-facts"><div class="detail-fact">${icon('clock',21)}<strong>${esc(r.minutes)} min</strong><small>Cooking time</small></div><div class="detail-fact">${icon('users',21)}<strong>${esc(r.servings)}</strong><small>Servings</small></div><div class="detail-fact">${icon('star',21)}<strong>${esc(r.difficulty)}</strong><small>Difficulty</small></div></div>
<section class="paper-card"><h3>Ingredients <small>${r.ingredients.length} items</small></h3><button class="btn small grocery-transfer" data-action="recipe-grocery-picker" data-id="${esc(r.id)}">${icon('basket',15)} Add to groceries</button>${r.ingredients.length?r.ingredients.map((ing,i)=>`<label class="ingredient"><input data-action="ingredient" data-index="${i}" type="checkbox" ${ingredientChecks.includes(i)?'checked':''}><span>${esc(ing)}</span></label>`).join(''):'<p class="hint">No ingredients added yet.</p>'}</section>
<section><h2 class="detail-section-label">Cooking steps</h2>${r.steps.map((s,i)=>`<article class="step-card"><div class="step-head"><span class="step-number">${i+1}</span><strong>${esc(s.text)}</strong></div>${s.note?`<p class="step-notes">${esc(s.note)}</p>`:''}${s.photo?`<img class="step-photo" src="${esc(s.photo)}" alt="Photo for step ${i+1}" loading="lazy">`:''}<button class="step-photo-btn" data-action="step-photo" data-id="${esc(r.id)}" data-step="${esc(s.id)}">${icon('camera',15)} ${s.photo?'Change step photo':'Add a photo for this step'} ${icon('plus',13)}</button></article>`).join('')}</section>
<section class="paper-card" style="margin-top:16px"><h3>Kitchen notes ${icon('leaf',20)}</h3>${r.notes?`<p class="diary-quote">“${esc(r.notes)}”</p>`:'<p class="hint">No notes yet.</p>'}<button class="btn ghost small" style="margin-top:10px" data-action="edit">${icon('edit')} ${r.notes?'Edit notes':'Add cooking notes'}</button></section>
<div class="action-row" style="margin:21px 0 7px"><button class="btn secondary" data-action="duplicate" data-id="${esc(r.id)}">${icon('copy')} Copy recipe</button><button class="btn danger" data-action="confirm-delete" data-id="${esc(r.id)}">${icon('trash')} Delete</button></div>`;}
function settingsView(){return `<div class="eyebrow">PREFERENCES</div><h1 class="page-title">Settings</h1>
<div class="glass setting-card"><h3>Appearance</h3><div class="setting-row"><div><strong>Ambient glow</strong><small>Background lighting and details</small></div><button class="switch ${prefs.glow?'on':''}" role="switch" aria-checked="${prefs.glow}" aria-label="Toggle ambient glow" data-action="toggle-glow"></button></div><div class="setting-row"><div><strong>Color palette</strong></div><button class="btn small secondary" data-action="toggle-theme">${prefs.theme==='cinnamon'?'Cinnamon':'Maple'}</button></div></div>
<div class="glass setting-card"><h3>Shopping</h3><label class="form-label" for="settings-budget">Shopping budget ($) · 0 = no limit</label><div class="inline-form"><input id="settings-budget" class="form-input" type="number" min="0" step="0.01" value="${esc(prefs.budget)}"><button class="btn small" data-action="save-budget">Save</button></div><div class="setting-row"><strong>${groceries.length} grocery items</strong><button class="btn small secondary" data-action="confirm-clear-bought">Remove purchased</button></div><div class="setting-row"><strong>Clear grocery list</strong><button class="btn danger small" data-action="confirm-clear-groceries">Clear list</button></div></div>
<div class="glass setting-card"><h3>Backups</h3><p>Export recipes, grocery list, and uploaded photos. Data stays on this device unless you export it.</p><div class="action-row"><button class="btn small" data-action="export">${icon('download')} Export</button><button class="btn small secondary" data-action="import">${icon('upload')} Import</button></div></div>
<div class="glass setting-card"><h3>Recipes</h3><div class="setting-row"><strong>${recipes.length} recipes saved</strong><button class="btn small ghost" data-action="restore-demos">Restore samples</button></div><div class="setting-row"><strong>Delete every recipe</strong><button class="btn danger small" data-action="confirm-clear">Delete all</button></div></div>
<p class="hint" style="text-align:center;margin:22px 0">Stored privately on this device · No automatic sync</p>`;}
function renderEditor(preserve=false){if(!editor)return;const current=root.querySelector('.sheet')?.scrollTop||0;root.innerHTML=`<div class="overlay" id="editor-overlay"><section class="sheet" role="dialog" aria-modal="true" aria-label="${editor.id?'Edit recipe':'New recipe'}"><div class="grip"></div><button class="mini-close" data-action="close" aria-label="Close editor">${icon('close')}</button><h2>${editor.id?'Edit your recipe':'Write a new recipe'}</h2>
<div class="form-group"><span class="form-label">Cover photo</span><img class="form-photo" src="${esc(editor.photo||CATS[editor.category]?.art||CATS.food.art)}" alt="Recipe cover preview"><button class="btn small secondary form-photo-btn" data-action="editor-photo">${icon('camera')} ${editor.photo?.startsWith('data:')?'Change cover photo':'Upload your own photo'}</button>${editor.photo?.startsWith('data:')?` <button class="btn small ghost" data-action="remove-editor-photo">Remove</button>`:''}</div>
<div class="form-group"><label class="form-label" for="f-title">Recipe name *</label><input id="f-title" class="form-input" data-field="title" maxlength="110" placeholder="e.g. Grandma's rice pudding" value="${esc(editor.title)}"></div>
<div class="form-group"><label class="form-label" for="f-description">Description (optional)</label><textarea id="f-description" class="form-input" data-field="description" rows="2" maxlength="600" placeholder="Optional description">${esc(editor.description)}</textarea></div>
<div class="form-cols"><div class="form-group"><label class="form-label" for="f-category">Category *</label><select id="f-category" class="form-input" data-field="category">${Object.entries(CATS).map(([k,c])=>`<option value="${k}" ${editor.category===k?'selected':''}>${c.label}</option>`).join('')}</select></div><div class="form-group"><label class="form-label" for="f-difficulty">Difficulty</label><select id="f-difficulty" class="form-input" data-field="difficulty">${['Easy','Medium','Cozy project'].map(x=>`<option ${editor.difficulty===x?'selected':''}>${x}</option>`).join('')}</select></div></div>
<div class="form-cols"><div class="form-group"><label class="form-label" for="f-time">Time (minutes) *</label><input id="f-time" type="number" min="1" max="9999" class="form-input" data-field="minutes" value="${esc(editor.minutes)}"></div><div class="form-group"><label class="form-label" for="f-servings">Servings *</label><input id="f-servings" type="number" min="1" max="999" class="form-input" data-field="servings" value="${esc(editor.servings)}"></div></div>
<div class="form-group"><label class="form-label" for="f-ingredients">Ingredients · One per line</label><textarea id="f-ingredients" class="form-input" data-field="ingredientsText" rows="6" placeholder="1 cup rice\n2 cups milk\n1 pinch cinnamon">${esc(editor.ingredientsText)}</textarea></div>
<div class="form-group"><label class="form-label" for="f-notes">Cooking notes</label><textarea id="f-notes" class="form-input" rows="3" data-field="notes" placeholder="Tips and substitutions">${esc(editor.notes)}</textarea></div>
<div class="section-heading" style="margin-top:20px"><h2>Cooking steps + photos</h2></div>
<div id="editor-steps">${editor.steps.map((s,i)=>`<div class="editor-step"><div class="editor-step-head"><span>Step ${i+1}</span><button class="btn small ghost" data-action="remove-step" data-step-index="${i}" aria-label="Remove step ${i+1}">${icon('trash',13)}</button></div><label class="form-label">What do we do?</label><textarea class="form-input" rows="2" data-step-field="text" data-step-index="${i}" placeholder="e.g. Soak the rice for 20 minutes">${esc(s.text)}</textarea><label class="form-label" style="margin-top:10px">Step notes (optional)</label><textarea class="form-input" rows="2" data-step-field="note" data-step-index="${i}" placeholder="Tip or reminder">${esc(s.note)}</textarea>${s.photo?`<img src="${esc(s.photo)}" alt="Photo for step ${i+1}">`:''}<div class="editor-controls"><button class="btn small secondary" data-action="editor-step-photo" data-step-index="${i}">${icon('camera',14)} ${s.photo?'Change photo':'Add step photo'}</button>${s.photo?`<button class="btn small ghost" data-action="remove-step-photo" data-step-index="${i}">Remove photo</button>`:''}</div></div>`).join('')}</div><button class="btn secondary wide" style="margin-top:12px" data-action="add-step">${icon('plus')} Add another cooking step</button>
<div class="sheet-actions"><button class="btn secondary" data-action="close">Cancel</button><button class="btn" data-action="save-recipe">${icon('check')} Save recipe</button></div></section></div>`;if(preserve){const sheet=root.querySelector('.sheet');sheet.scrollTop=current;}}
function syncEditor(){if(!editor)return;root.querySelectorAll('[data-field]').forEach(el=>{editor[el.dataset.field]=el.value;});root.querySelectorAll('[data-step-field]').forEach(el=>{const s=editor.steps[Number(el.dataset.stepIndex)];if(s)s[el.dataset.stepField]=el.value;});}
function openEditor(recipe){if(recipe){editor={...structuredClone(recipe),ingredientsText:(recipe.ingredients||[]).join('\n'),steps:structuredClone(recipe.steps||[])};}else{editor={id:null,title:'',description:'',category:['food','drink','dessert'].includes(tab)?tab:'food',minutes:30,servings:4,difficulty:'Easy',photo:'',favorite:false,ingredientsText:'',notes:'',steps:[{id:id(),text:'',note:'',photo:''}]};}overlay='editor';renderEditor();}
function closeOverlay(){overlay='';editor=null;groceryDraft=null;root.innerHTML='';}
function confirmModal(title,message,action,label){overlay='confirm';root.innerHTML=`<div class="overlay"><section class="sheet confirm-sheet" role="alertdialog" aria-modal="true" aria-labelledby="confirm-title"><div class="grip"></div><button class="mini-close" data-action="close" aria-label="Cancel">${icon('close')}</button><h2 id="confirm-title">${esc(title)}</h2><p>${esc(message)}</p><div class="sheet-actions"><button class="btn secondary" data-action="close">Keep it</button><button class="btn danger" data-action="${action}">${icon('trash')} ${esc(label)}</button></div></section></div>`;}
async function saveEditor(){syncEditor();const r=editor;const title=r.title.trim();const ingredients=r.ingredientsText.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);const steps=r.steps.map(s=>({...s,text:s.text.trim(),note:(s.note||'').trim()})).filter(s=>s.text);if(!title){notify('Enter a recipe name');root.querySelector('#f-title')?.focus();return;}if(!(Number(r.minutes)>0)||!(Number(r.servings)>0)){notify('Add a cooking time and servings');return;}if(!steps.length){notify('Add at least one cooking step');return;}const now=new Date().toISOString();const old=r.id?byId(r.id):null;const data={id:r.id||id(),title:title.slice(0,110),category:CATS[r.category]?r.category:'food',description:r.description.trim().slice(0,600),minutes:Math.round(Number(r.minutes)),servings:Math.round(Number(r.servings)),difficulty:['Easy','Medium','Cozy project'].includes(r.difficulty)?r.difficulty:'Easy',photo:r.photo||'',notes:r.notes.trim(),ingredients,steps,createdAt:old?.createdAt||now,updatedAt:now,favorite:old?.favorite||false};try{await put('recipes',data);recipes=recipes.filter(x=>x.id!==data.id).concat(data);selected=data.id;tab='recipes';closeOverlay();render();notify('Recipe saved');}catch(e){console.error(e);notify('Unable to save. Check storage space.');}}
async function updateRecipe(r){const updated={...r,updatedAt:new Date().toISOString()};try{await put('recipes',updated);recipes=recipes.map(x=>x.id===r.id?updated:x);return true;}catch(e){console.error(e);notify('Could not save. Your storage may be full.');return false;}}
function activateTab(next){selected=null;tab=next;previousTab=next==='settings'?previousTab:next;query='';filter='all';favoritesOnly=false;render();}
function pickPhoto(target){photoTarget=target;const input=$('#media-picker');input.value='';input.click();}
function compressPhoto(file){return new Promise((resolve,reject)=>{if(file.size>25*1024*1024)return reject(Error('Please choose a photo under 25 MB.'));const url=URL.createObjectURL(file),im=new Image();im.onload=()=>{try{const max=1450,scale=Math.min(1,max/Math.max(im.width,im.height)),can=document.createElement('canvas');can.width=Math.round(im.width*scale);can.height=Math.round(im.height*scale);const ctx=can.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,can.width,can.height);ctx.drawImage(im,0,0,can.width,can.height);const data=can.toDataURL('image/jpeg',.83);URL.revokeObjectURL(url);resolve(data);}catch(err){URL.revokeObjectURL(url);reject(err);}};im.onerror=()=>{URL.revokeObjectURL(url);reject(Error('This image could not be opened.'));};im.src=url;});}
async function handlePhoto(file){if(!file||!photoTarget)return;if(!file.type.startsWith('image/')){notify('Please select an image');return;}const target=photoTarget;photoTarget=null;try{const url=await compressPhoto(file);if(target.editor){if(!editor)return;syncEditor();if(target.type==='cover')editor.photo=url;else{const step=editor.steps.find(s=>s.id===target.stepId);if(!step)return;step.photo=url;}renderEditor(true);notify('Photo added to draft');}else{const r=byId(target.recipeId);if(!r)return;const updated=structuredClone(r);if(target.type==='cover')updated.photo=url;else{const step=updated.steps.find(s=>s.id===target.stepId);if(!step)return;step.photo=url;}if(await updateRecipe(updated)){const y=screen.scrollTop;render({keepScroll:true});screen.scrollTop=y;notify('Photo saved');}}}catch(err){console.error(err);notify(err.message||'Photo could not be added');}}
async function toggleFavorite(rid){const r=byId(rid);if(!r)return;const ok=await updateRecipe({...r,favorite:!r.favorite});if(ok){render({keepScroll:true});notify(r.favorite?'Removed from favorites':'Added to favorites');}}
async function exportBackup(){const data={app:'the-little-kitchen',version:2,exportedAt:new Date().toISOString(),recipes,groceries,prefs};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`little-kitchen-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Backup downloaded');}
function exportGroceryCsv(){
 const columns=['Item','Quantity','Unit','Aisle','Store','Unit price','Estimated total','Important','Purchased','Notes','Recipe'];
 const rows=groceries.map(g=>[g.name,prettyQty(g.qty),g.unit,GROCERIES[g.category]?.name||'Other',g.store,g.price,(g.qty*g.price).toFixed(2),g.priority?'Yes':'No',g.checked?'Yes':'No',g.notes,g.source]);
 const csv=[columns,...rows].map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');
 const blob=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`little-kitchen-groceries-${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Grocery CSV downloaded');
}
function validateImported(r){if(!r||typeof r!=='object'||!r.title||!Array.isArray(r.steps)||!Array.isArray(r.ingredients))return null;const safePhoto=x=>typeof x==='string'&&(x.startsWith('data:image/')&&x.length<10000000||x.startsWith('./assets/'))?x:'';return {id:id(),title:String(r.title).slice(0,110),category:CATS[r.category]?r.category:'food',description:String(r.description||'').slice(0,600),minutes:Math.max(1,Math.min(9999,Number(r.minutes)||30)),servings:Math.max(1,Math.min(999,Number(r.servings)||4)),difficulty:['Easy','Medium','Cozy project'].includes(r.difficulty)?r.difficulty:'Easy',photo:safePhoto(r.photo),favorite:!!r.favorite,notes:String(r.notes||'').slice(0,10000),ingredients:r.ingredients.slice(0,150).map(s=>String(s).slice(0,500)),steps:r.steps.slice(0,100).map(s=>({id:id(),text:String(s.text||'').slice(0,3000),note:String(s.note||'').slice(0,3000),photo:safePhoto(s.photo)})),createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};}
async function importBackup(file){try{
 if(file.size>90*1024*1024)throw Error('Backup is too large.');const obj=JSON.parse(await file.text());
 if(obj.app!=='the-little-kitchen'||!Array.isArray(obj.recipes))throw Error('Not a Little Kitchen backup.');
 const imported=obj.recipes.map(validateImported).filter(Boolean);const importedGroceries=(Array.isArray(obj.groceries)?obj.groceries:[]).slice(0,3000).map(validateGrocery).filter(Boolean);
 if(!imported.length&&!importedGroceries.length)throw Error('No valid recipes or groceries in backup.');
 for(const r of imported)await put('recipes',r);for(const g of importedGroceries)await put('groceries',g);
 recipes=await readAll('recipes');groceries=await readAll('groceries');selected=null;closeOverlay();activateTab('grocery');notify(`Imported ${imported.length} recipes and ${importedGroceries.length} grocery items`);
 }catch(e){console.error(e);notify(e.message||'Import failed');}
}
async function restoreDemos(){try{let count=0;for(const d of demo){if(!byId(d.id)){await put('recipes',d);recipes.push(d);count++;}}render({keepScroll:true});notify(count?`Restored ${count} starter recipes`:'All starter recipes are already here');}catch(e){console.error(e);notify('Could not restore starter recipes');}}
async function duplicateRecipe(rid){const r=byId(rid);if(!r)return;const cloned=structuredClone(r),now=new Date().toISOString();cloned.id=id();cloned.title=`${r.title} (copy)`;cloned.createdAt=now;cloned.updatedAt=now;cloned.steps=cloned.steps.map(s=>({...s,id:id()}));if(await updateRecipe(cloned)){recipes.push(cloned);selected=cloned.id;render();notify('A copy is ready for you ♡');}}

// GROCERY LIST — persistent, editable shopping items.
const GROCERIES={produce:{name:'Produce',symbol:'🍎'},dairy:{name:'Dairy & eggs',symbol:'🥛'},meat:{name:'Meat & seafood',symbol:'🍗'},bakery:{name:'Bakery',symbol:'🥖'},pantry:{name:'Pantry',symbol:'🫙'},frozen:{name:'Frozen',symbol:'❄️'},drinks:{name:'Drinks',symbol:'🫖'},household:{name:'Household',symbol:'🧺'},other:{name:'Other',symbol:'✦'}};
const UNITS=['','pcs','oz','lb','g','kg','ml','L','cup','cups','tsp','tbsp','can','cans','bag','bags','box','bottle','bunch','cloves','slices','package'];
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(n)||0);
const prettyQty=n=>Number.isInteger(Number(n))?String(n):String(Number(Number(n).toFixed(2)));
const safeMoney=n=>Math.max(0,Math.min(999999,Number(n)||0));
function detectCategory(name){const s=name.toLowerCase();const groups={produce:/apple|banana|orange|lemon|lime|onion|garlic|tomato|potato|lettuce|pumpkin|basil|parsley|cilantro|herb|pepper|carrot|ginger|berry|berries|fruit|vegetable|salad|avocado|spinach/,dairy:/milk|butter|cream|egg|cheese|yogurt|parmesan/,meat:/chicken|beef|turkey|fish|salmon|shrimp|pork|bacon|steak/,bakery:/bread|bagel|roll|croissant|bun|tortilla/,frozen:/frozen|ice cream|popsicle/,drinks:/juice|soda|coffee|tea bag|cider|sparkling water/,household:/paper|soap|detergent|cleaner|foil|trash bag|towel/};return Object.keys(groups).find(k=>groups[k].test(s))||'pantry';}
function fractionNumber(raw){const lookup={'¼':.25,'½':.5,'¾':.75,'⅓':1/3,'⅔':2/3,'⅛':.125,'⅜':.375,'⅝':.625,'⅞':.875};let s=String(raw).trim();if(s.includes('/')){const parts=s.split(' ');const f=parts.pop().split('/').map(Number);return (Number(parts[0])||0)+f[0]/f[1];}if(Object.keys(lookup).some(f=>s.includes(f))){let n=0;for(const [f,v] of Object.entries(lookup)){if(s.includes(f)){n=v;s=s.replace(f,'');break;}}return (Number(s)||0)+n;}return Number(s)||1;}
function ingredientToGrocery(ingredient,recipeTitle){let text=String(ingredient).trim().replace(/^[-•]\s*/,'');const m=text.match(/^(\d+(?:\.\d+)?(?:\s+\d+\/\d+)?|\d+\/\d+|\d*[¼½¾⅓⅔⅛⅜⅝⅞])\s+(.+)$/u);let qty=1,unit='',name=text;
 if(m){qty=fractionNumber(m[1]);name=m[2];const unitRx=/^(tbsp|tsp|cups?|cloves?|cans?|bags?|boxes?|oz|lb|lbs|g|kg|ml|l|bottles?|bunch(?:es)?|slices?|packages?|pcs?)\b\.?\s*/i;const found=name.match(unitRx);if(found){unit=found[1].toLowerCase();name=name.slice(found[0].length);} }
 name=name.replace(/^of\s+/i,'').trim()||text;return {id:id(),name:name.slice(0,140),qty:Math.max(0.01,qty),unit,category:detectCategory(name),store:'',price:0,checked:false,priority:false,notes:'',source:recipeTitle||'',createdAt:new Date().toISOString()};}
function validateGrocery(g){if(!g||typeof g!=='object'||typeof g.name!=='string'||!g.name.trim())return null;const name=g.name.trim().slice(0,140);return {id:id(),name,qty:Math.max(.01,Math.min(99999,Number(g.qty)||1)),unit:String(g.unit||'').slice(0,25),category:GROCERIES[g.category]?g.category:detectCategory(name),store:String(g.store||'').slice(0,80),price:safeMoney(g.price),checked:!!g.checked,priority:!!g.priority,notes:String(g.notes||'').slice(0,500),source:String(g.source||'').slice(0,120),createdAt:new Date().toISOString()};}
async function saveGrocery(item){const name=String(item.name||'').trim();if(!name){notify('Enter an item name');return false;}const obj={...item,name:name.slice(0,140),qty:Math.max(.01,Math.min(99999,Number(item.qty)||1)),unit:String(item.unit||'').slice(0,25),category:GROCERIES[item.category]?item.category:detectCategory(name),store:String(item.store||'').trim().slice(0,80),price:safeMoney(item.price),checked:!!item.checked,priority:!!item.priority,notes:String(item.notes||'').trim().slice(0,500)};
 try{await put('groceries',obj);groceries=groceries.filter(g=>g.id!==obj.id).concat(obj);return true;}catch(err){console.error(err);notify('Could not save grocery item');return false;}}
async function insertGrocery(item){const key=x=>[x.name.toLowerCase().replace(/\s+/g,' ').trim(),x.unit.toLowerCase(),x.store.toLowerCase()].join('|');const prev=groceries.find(g=>!g.checked&&key(g)===key(item));if(prev){await saveGrocery({...prev,qty:Number(prev.qty)+Number(item.qty),source:prev.source||item.source});return 'merged';}await saveGrocery(item);return 'added';}
function groceryView(){const total=groceries.length,done=groceries.filter(g=>g.checked).length,needed=total-done,expected=groceries.reduce((s,g)=>s+g.qty*g.price,0),remaining=groceries.filter(g=>!g.checked).reduce((s,g)=>s+g.qty*g.price,0),progress=total?Math.round(done/total*100):0;
 const stores=[...new Set(groceries.map(g=>g.store).filter(Boolean))].sort();const text=grocerySearch.toLowerCase();const found=groceries.filter(g=>(groceryFilter==='all'||(groceryFilter==='needed'?!g.checked:groceryFilter==='bought'?g.checked:g.priority&&!g.checked))&&(groceryCategory==='all'||g.category===groceryCategory)&&(groceryStore==='all'||g.store===groceryStore)&&[g.name,g.notes,g.source,g.store].some(x=>x.toLowerCase().includes(text)));
 const grouping=groceryGroup==='store'?'store':'category';const order=grouping==='store'?['Unassigned',...stores]:Object.keys(GROCERIES);const groups=new Map();for(const g of found){const key=grouping==='store'?(g.store||'Unassigned'):g.category;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(g);}const sortedGroups=[...groups.keys()].sort((x,y)=>order.indexOf(x)-order.indexOf(y));
 return `<section class="grocery-head"><div class="grocery-illustration" aria-hidden="true"></div><div class="grocery-head-content"><div class="eyebrow">MY SHOPPING LIST</div><h1 class="page-title">Groceries<span class="sparkle">✦</span></h1><div class="grocery-status"><strong>${needed}</strong> to buy <span class="status-separator">·</span> <strong>${done}</strong> in basket</div></div></section>
 <div class="grocery-meter"><div class="meter-rail"><span style="width:${progress}%"></span></div><div class="meter-description"><span>${progress}% complete</span><span>${money(remaining)} remaining${prefs.budget?` / ${money(prefs.budget)} budget`:''}</span></div></div>
 <form class="grocery-quick" id="grocery-quick-form"><label class="sr-only" for="grocery-quick-input">Quick add grocery item</label><input id="grocery-quick-input" autocomplete="off" maxlength="140" placeholder="Add milk, apples, rice…" required><button type="submit" aria-label="Quick add item">${icon('plus',22)}</button></form>
 <div class="grocery-actions"><button class="btn small secondary" data-action="grocery-new">${icon('edit',14)} Item details</button><button class="btn small" data-action="grocery-pick-recipes">${icon('book',14)} Add from recipe</button></div>
 <div class="grocery-toolbar"><div class="chip-list shopping-chips">${[['all','All'],['needed','To buy'],['bought','Bought'],['priority','Important']].map(([key,label])=>`<button class="chip ${groceryFilter===key?'selected':''}" data-action="grocery-filter" data-value="${key}">${label}${key==='all'?` ${total}`:key==='needed'?` ${needed}`:key==='bought'?` ${done}`:''}</button>`).join('')}</div>
 <div class="grocery-tools"><label class="search-bar grocery-search">${icon('search',16)}<input id="grocery-search" type="search" aria-label="Search grocery items" value="${esc(grocerySearch)}" placeholder="Search items…"></label><select id="grocery-store" class="grocery-select" aria-label="Filter by store"><option value="all">All stores</option>${stores.map(s=>`<option value="${esc(s)}" ${groceryStore===s?'selected':''}>${esc(s)}</option>`).join('')}</select></div>
 <div class="grocery-tools"><select id="grocery-category" class="grocery-select" aria-label="Filter by category"><option value="all">All aisles</option>${Object.entries(GROCERIES).map(([key,c])=>`<option value="${key}" ${groceryCategory===key?'selected':''}>${esc(c.name)}</option>`).join('')}</select><div class="grocery-group-control"><span>${icon('sort',14)}</span><select id="grocery-group" class="grocery-select" aria-label="Group list by"><option value="category" ${grouping==='category'?'selected':''}>By aisle</option><option value="store" ${grouping==='store'?'selected':''}>By store</option></select></div></div></div>
 <section class="shopping-list" aria-label="Shopping items">${sortedGroups.length?sortedGroups.map(key=>`<div class="grocery-group"><div class="grocery-group-head"><span>${grouping==='category'?GROCERIES[key]?.symbol||'✦':'🛒'}</span><h2>${esc(grouping==='category'?GROCERIES[key]?.name||'Other':key)}</h2><small>${groups.get(key).length}</small></div>${groups.get(key).sort((a,b)=>Number(a.checked)-Number(b.checked)||Number(b.priority)-Number(a.priority)||a.name.localeCompare(b.name)).map(g=>`<div class="grocery-item ${g.checked?'is-bought':''}"><label class="grocery-checkbox" title="${g.checked?'Mark to buy':'Mark purchased'}"><input type="checkbox" data-action="grocery-toggle" data-id="${esc(g.id)}" ${g.checked?'checked':''}><span class="grocery-tick">${icon('check',16)}</span></label><button class="grocery-item-main" data-action="grocery-edit" data-id="${esc(g.id)}"><span class="grocery-item-title">${esc(g.name)}${g.priority?'<b class="important-star" title="Important">★</b>':''}</span><span class="grocery-item-meta">${esc(prettyQty(g.qty))}${g.unit?' '+esc(g.unit):''}${g.store?' · '+esc(g.store):''}${g.source?' · '+esc(g.source):''}${g.notes?' · '+esc(g.notes):''}</span></button>${g.price?`<span class="grocery-item-price">${money(g.qty*g.price)}</span>`:''}<button class="grocery-edit-btn" data-action="grocery-edit" data-id="${esc(g.id)}" aria-label="Edit ${esc(g.name)}">${icon('edit',15)}</button></div>`).join('')}</div>`).join(''):`<div class="grocery-empty"><span class="grocery-empty-art" aria-hidden="true">${icon('basket',48)}</span><h3>${total?'No matching items':'Your list is empty'}</h3><p>${total?'Try another filter.':'Add items above or import ingredients from a recipe.'}</p></div>`}</section>
 ${total?`<footer class="grocery-footer"><span>${total} items · ${money(expected)} estimated total</span><div><button data-action="grocery-csv">Export CSV</button><button data-action="confirm-clear-bought" ${!done?'disabled':''}>Clear bought</button></div></footer>`:''}<button class="floating-add" data-action="grocery-new" aria-label="Add detailed grocery item">${icon('plus',25)}</button>`;
}
function openGroceryEditor(existing){const g=existing?{...existing}:{id:id(),name:'',qty:1,unit:'',category:'pantry',store:'',price:0,priority:false,checked:false,notes:'',source:'',createdAt:new Date().toISOString()};groceryDraft=g;overlay='grocery-editor';root.innerHTML=`<div class="overlay"><section class="sheet" role="dialog" aria-modal="true" aria-label="${existing?'Edit':'Add'} grocery item"><div class="grip"></div><button class="mini-close" data-action="close" aria-label="Close">${icon('close')}</button><h2>${existing?'Edit item':'Add grocery item'}</h2><form id="grocery-item-form"><div class="form-group"><label class="form-label" for="g-name">Item name *</label><input class="form-input" id="g-name" name="name" maxlength="140" required value="${esc(g.name)}" placeholder="e.g. Whole milk"></div>
 <div class="form-cols"><div class="form-group"><label class="form-label" for="g-qty">Quantity</label><input id="g-qty" class="form-input" type="number" name="qty" value="${esc(g.qty)}" step="0.01" min="0.01" max="99999"></div><div class="form-group"><label class="form-label" for="g-unit">Unit</label><input id="g-unit" list="unit-options" class="form-input" name="unit" value="${esc(g.unit)}" maxlength="25" placeholder="e.g. cups"><datalist id="unit-options">${UNITS.map(u=>`<option value="${u}">`).join('')}</datalist></div></div>
 <div class="form-cols"><div class="form-group"><label class="form-label" for="g-cat">Aisle</label><select class="form-input" name="category" id="g-cat">${Object.entries(GROCERIES).map(([key,c])=>`<option value="${key}" ${g.category===key?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="form-group"><label class="form-label" for="g-store-edit">Store</label><input class="form-input" id="g-store-edit" name="store" maxlength="80" value="${esc(g.store)}" placeholder="Any store"></div></div>
 <div class="form-group"><label class="form-label" for="g-price">Estimated price per unit ($)</label><input class="form-input" id="g-price" type="number" name="price" min="0" max="999999" step="0.01" value="${esc(g.price)}"></div>
 <div class="form-group"><label class="form-label" for="g-notes">Notes (optional)</label><textarea id="g-notes" class="form-input" name="notes" maxlength="500" rows="2" placeholder="Brand, size or substitution">${esc(g.notes)}</textarea></div><div class="grocery-toggles"><label><input type="checkbox" name="priority" ${g.priority?'checked':''}> Important</label><label><input type="checkbox" name="checked" ${g.checked?'checked':''}> Already bought</label></div>
 <div class="sheet-actions">${existing?`<button type="button" class="btn danger" data-action="grocery-ask-remove" data-id="${esc(g.id)}">${icon('trash')} Delete</button>`:''}<button class="btn" type="submit">${icon('check')} Save item</button></div></form></section></div>`;root.querySelector('#g-name')?.focus();}
function openRecipePicker(recipeId){const r=byId(recipeId)||sortRec(recipes).find(x=>x.ingredients?.length);if(!r){notify('Add a recipe with ingredients first');return;}groceryPickerRecipe=r.id;groceryPickerSelected=new Set(r.ingredients.map((_,i)=>i));overlay='grocery-picker';renderRecipePicker();}
function renderRecipePicker(){const r=byId(groceryPickerRecipe);if(!r)return;root.innerHTML=`<div class="overlay"><section class="sheet" role="dialog" aria-modal="true" aria-label="Add ingredients to grocery list"><div class="grip"></div><button class="mini-close" data-action="close" aria-label="Close">${icon('close')}</button><h2>From a recipe</h2><label class="form-label" for="picker-recipe">Choose a recipe</label><select class="form-input" id="picker-recipe">${sortRec(recipes).map(x=>`<option value="${esc(x.id)}" ${x.id===r.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select><div class="picker-toolbar"><strong>${groceryPickerSelected.size} selected</strong><button class="btn small ghost" data-action="picker-select-all">Select all</button><button class="btn small ghost" data-action="picker-select-none">None</button></div><div class="picker-list">${r.ingredients.map((ing,i)=>`<label class="picker-ingredient"><input type="checkbox" data-action="picker-check" data-index="${i}" ${groceryPickerSelected.has(i)?'checked':''}><span>${esc(ing)}</span></label>`).join('')||'<p class="hint">This recipe has no ingredients.</p>'}</div><div class="sheet-actions"><button class="btn secondary" data-action="close">Cancel</button><button class="btn" data-action="picker-add">${icon('basket')} Add selected</button></div></section></div>`;}
async function addPickedIngredients(){const r=byId(groceryPickerRecipe);if(!r)return;const indices=[...groceryPickerSelected].sort((a,b)=>a-b);if(!indices.length){notify('Select an ingredient');return;}for(const i of indices){if(r.ingredients[i])await insertGrocery(ingredientToGrocery(r.ingredients[i],r.title));}closeOverlay();selected=null;activateTab('grocery');notify(`Added ${indices.length} ingredients to your list`);}

// Delegated controls: cover art, category tabs, notes, editor, photos and backups.
document.addEventListener('click',async e=>{const btn=e.target.closest('[data-tab],[data-action]');if(!btn)return;if(btn.dataset.tab){activateTab(btn.dataset.tab);return;}const action=btn.dataset.action,rid=btn.dataset.id||selected;switch(action){
case 'back':selected=null;render();break;
case 'settings':if(tab!=='settings')previousTab=tab;selected=null;tab='settings';render();break;
case 'settings-back':activateTab(previousTab||'grocery');break;
case 'grocery-new':openGroceryEditor(null);break;
case 'grocery-csv':exportGroceryCsv();break;
case 'grocery-edit':openGroceryEditor(groceries.find(g=>g.id===btn.dataset.id));break;
case 'grocery-filter':groceryFilter=btn.dataset.value;render({keepScroll:true});break;
case 'grocery-pick-recipes':openRecipePicker(null);break;
case 'recipe-grocery-picker':openRecipePicker(rid);break;
case 'picker-select-all':groceryPickerSelected=new Set(byId(groceryPickerRecipe).ingredients.map((_,i)=>i));renderRecipePicker();break;
case 'picker-select-none':groceryPickerSelected.clear();renderRecipePicker();break;
case 'picker-add':await addPickedIngredients();break;
case 'grocery-ask-remove':pendingGroceryId=btn.dataset.id;confirmModal('Delete grocery item?','Remove this item from the shopping list?','grocery-remove','Delete');break;
case 'grocery-remove':if(pendingGroceryId){await del('groceries',pendingGroceryId);groceries=groceries.filter(g=>g.id!==pendingGroceryId);pendingGroceryId=null;closeOverlay();render({keepScroll:true});notify('Item deleted');}break;
case 'confirm-clear-bought':confirmModal('Remove purchased items?','Only checked-off grocery items will be removed.','clear-bought','Remove bought');break;
case 'clear-bought':for(const g of groceries.filter(x=>x.checked))await del('groceries',g.id);groceries=groceries.filter(x=>!x.checked);closeOverlay();render();notify('Purchased items removed');break;
case 'confirm-clear-groceries':confirmModal('Clear shopping list?','This deletes every item in your grocery list.','clear-groceries','Clear list');break;
case 'clear-groceries':await clear('groceries');groceries=[];closeOverlay();render();notify('Shopping list cleared');break;
case 'save-budget':prefs.budget=Math.max(0,safeMoney($('#settings-budget')?.value));await put('meta',{key:'budget',value:prefs.budget});render({keepScroll:true});notify('Budget saved');break;
case 'open':selected=rid;render();break;
case 'new':openEditor(null);break;
case 'edit':openEditor(byId(selected));break;
case 'favorite':await toggleFavorite(rid);break;
case 'clear-filter':favoritesOnly=false;filter='all';render({keepScroll:true});break;
case 'fav-filter':favoritesOnly=!favoritesOnly;render({keepScroll:true});break;
case 'difficulty':filter=filter===btn.dataset.value?'all':btn.dataset.value;render({keepScroll:true});break;
case 'close':closeOverlay();break;
case 'save-recipe':await saveEditor();break;
case 'add-step':syncEditor();editor.steps.push({id:id(),text:'',note:'',photo:''});renderEditor(true);setTimeout(()=>{const sheet=root.querySelector('.sheet');if(sheet)sheet.scrollTop=sheet.scrollHeight-230;},0);break;
case 'remove-step':syncEditor();if(editor.steps.length<=1){notify('Keep at least one cooking step');return;}editor.steps.splice(Number(btn.dataset.stepIndex),1);renderEditor(true);break;
case 'editor-photo':syncEditor();pickPhoto({editor:true,type:'cover'});break;
case 'remove-editor-photo':syncEditor();editor.photo='';renderEditor(true);break;
case 'editor-step-photo':syncEditor();pickPhoto({editor:true,type:'step',stepId:editor.steps[Number(btn.dataset.stepIndex)].id});break;
case 'remove-step-photo':syncEditor();editor.steps[Number(btn.dataset.stepIndex)].photo='';renderEditor(true);break;
case 'step-photo':pickPhoto({editor:false,type:'step',recipeId:rid,stepId:btn.dataset.step});break;
case 'confirm-delete':confirmModal('Delete this recipe?','This will permanently remove this recipe and all of its step photos from this browser. Export a backup first if you want to keep it.','delete-recipe','Delete recipe');break;
case 'delete-recipe':if(selected){await del('recipes',selected);recipes=recipes.filter(r=>r.id!==selected);selected=null;closeOverlay();render();notify('Recipe removed');}break;
case 'duplicate':await duplicateRecipe(rid);break;
case 'toggle-glow':prefs.glow=!prefs.glow;await put('meta',{key:'glow',value:prefs.glow});render({keepScroll:true});break;
case 'toggle-theme':prefs.theme=prefs.theme==='cinnamon'?'maple':'cinnamon';await put('meta',{key:'theme',value:prefs.theme});render({keepScroll:true});break;
case 'export':exportBackup();break;
case 'import':$('#import-picker').click();break;
case 'restore-demos':await restoreDemos();break;
case 'confirm-clear':confirmModal('Clear your entire cookbook?','This permanently deletes every saved recipe, cooking note, and uploaded photo from this browser. Export a backup before proceeding.','clear-recipes','Clear cookbook');break;
case 'clear-recipes':await clear('recipes');recipes=[];selected=null;closeOverlay();render();notify('Cookbook cleared');break;
}});
document.addEventListener('input',e=>{if(e.target.id==='grocery-search'){const input=e.target,pos=input.selectionStart;grocerySearch=input.value;render({keepScroll:true});const again=$('#grocery-search');again?.focus();try{again?.setSelectionRange(pos,pos);}catch{}return;}if(e.target.id==='recipe-search'){const val=e.target.value,start=e.target.selectionStart;query=val;const scroll=screen.scrollTop;render({keepScroll:true});const input=$('#recipe-search');input?.focus();try{input?.setSelectionRange(start,start);}catch{}screen.scrollTop=scroll;}});
document.addEventListener('change',async e=>{if(e.target.dataset.action==='grocery-toggle'){const g=groceries.find(g=>g.id===e.target.dataset.id);if(g&&await saveGrocery({...g,checked:e.target.checked}))render({keepScroll:true});return;}if(e.target.dataset.action==='picker-check'){const idx=Number(e.target.dataset.index);if(e.target.checked)groceryPickerSelected.add(idx);else groceryPickerSelected.delete(idx);root.querySelector('.picker-toolbar strong').textContent=groceryPickerSelected.size+' selected';return;}if(e.target.id==='picker-recipe'){groceryPickerRecipe=e.target.value;groceryPickerSelected=new Set((byId(groceryPickerRecipe)?.ingredients||[]).map((_,i)=>i));renderRecipePicker();return;}if(e.target.id==='grocery-category'){groceryCategory=e.target.value;render({keepScroll:true});return;}if(e.target.id==='grocery-store'){groceryStore=e.target.value;render({keepScroll:true});return;}if(e.target.id==='grocery-group'){groceryGroup=e.target.value;render({keepScroll:true});return;}if(e.target.dataset.action==='ingredient'){const i=Number(e.target.dataset.index);const a=checked[selected]||[];checked[selected]=e.target.checked?[...a.filter(x=>x!==i),i]:a.filter(x=>x!==i);}});
document.addEventListener('submit',async e=>{if(e.target.id==='grocery-quick-form'){e.preventDefault();const input=e.target.querySelector('input');const name=input.value.trim();if(!name)return;const g=ingredientToGrocery(name,'');g.name=name;g.qty=1;g.unit='';if(await saveGrocery(g)){render({keepScroll:true});$('#grocery-quick-input')?.focus();notify('Item added');}return;}if(e.target.id==='grocery-item-form'){e.preventDefault();const form=e.target;const data=new FormData(form);const original=groceryDraft||{};const g={...original,name:data.get('name'),qty:data.get('qty'),unit:data.get('unit'),category:data.get('category'),store:data.get('store'),price:data.get('price'),notes:data.get('notes'),priority:data.has('priority'),checked:data.has('checked')};if(await saveGrocery(g)){closeOverlay();render({keepScroll:true});notify('Item saved');}}});
$('#media-picker').addEventListener('change',e=>handlePhoto(e.target.files?.[0]));
$('#import-picker').addEventListener('change',e=>{const f=e.target.files?.[0];e.target.value='';if(f)importBackup(f);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&overlay)closeOverlay();});
initialize();
})();
